    {
      name: 'text_transform',
      description: 'Transform text using the specified mode.',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
          mode: { type: 'string', enum: MODES },
          trim: { type: 'boolean' }
        },
        required: ['text', 'mode'],
        additionalProperties: false
      }
    }
  ];
}

function applyTrim(text, trim) {
  return trim ? text.trim() : text;
}

function applyMode(text, mode, trim) {
  const trimmed = applyTrim(text, trim);
  switch (mode) {
    case 'uppercase':
      return trimmed.toUpperCase();
    case 'lowercase':
      return trimmed.toLowerCase();
    case 'slug':
      return trimmed
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
    default:
      throw new Error('Unknown mode: ' + mode);
  }
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error('Unknown tool: ' + name);
  }

  const allowed = { text: true, mode: true, trim: true };
  const keys = Object.keys(args);
  for (const k of keys) {
    if (!allowed[k]) {
      throw new Error('Unexpected argument: ' + k);
    }
  }

  if (args.text === undefined || args.text === null) {
    throw new Error('Missing required argument: text');
  }
  if (typeof args.text !== 'string') {
    throw new Error('Argument "text" must be a string');
  }

  if (args.mode === undefined || args.mode === null) {
    throw new Error('Missing required argument: mode');
  }
  if (typeof args.mode !== 'string') {
    throw new Error('Argument "mode" must be a string');
  }
  if (!MODES.includes(args.mode)) {
    throw new Error('Invalid mode: ' + args.mode);
  }

  let trim = true;
  if (args.trim !== undefined && args.trim !== null) {
    if (typeof args.trim !== 'boolean') {
      throw new Error('Argument "trim" must be a boolean');
    }
    trim = args.trim;
  }

  const result = applyMode(args.text, args.mode, trim);
  return {
    content: [{ type: 'text', text: result }]
  };
}

